    prompt=load(R/'raw/prompt-modes-selection.json');base=load(R/'raw/baseline-summary.json');longs=load(long_summary_path())['runs'];compaction=load(R/'raw/COMPACTION-FINAL-v0132-done.json')['runs'];agents={t:load(R/'raw'/f'{agent_label(t)}-done.json')['runs'] for t in [63400,127000]}
